#!/usr/bin/env python3
"""Authors the SECOND day of the Six-Day War (6 June 1967) for /war/: writes war/data/1967-06-06.json (page text + timeline), war/data/1967-06-06-events.json
(places, events, animation scene) and adds the day-2 casualty events ("jun6") to war/data/1967-casualties.json.

Same rules as 5 June: every event carries a short quote from a pinned he.wikipedia revision (elisions marked [...], names of anyone killed left out), times are the
article's own wording, everything not given a coordinate is drawn SCHEMATICALLY and labelled so. Run: python3 tools/war_data_1967_06_06.py
"""
import copy
import json
from pathlib import Path
DATA = Path(__file__).resolve().parent.parent / "war" / "data"
D1 = json.loads((DATA / "1967-06-05-events.json").read_text(encoding="utf-8"))
CAS = json.loads((DATA / "1967-casualties.json").read_text(encoding="utf-8"))

def pl(name, lat, lon, basis_kind="נקודת המקום"):
    return {"name": name, "lat": lat, "lon": lon, "precision": "exact", "basis": f'קואורדינטות הערך "{name}" בוויקיפדיה העברית ({basis_kind})'}
PLACES = copy.deepcopy(D1["places"])
PLACES.update({
    "latrun": pl("לטרון", 31.8334913, 35.02360525), "ramallah": pl("רמאללה", 31.9, 35.2, "נקודת העיר"), "jenin": pl("ג'נין", 32.45638889, 35.29583333, "נקודת העיר"),
    "qalqilya": pl("קלקיליה", 32.19037778, 34.96850833, "נקודת העיר"), "mivtar": pl("גבעת המבתר", 31.80305833, 35.23128611), "sheikh": pl("שייח' ג'ראח", 31.79458333, 35.231875),
    "rock": pl("מוזיאון רוקפלר", 31.78444444, 35.23583333), "hasana": pl("ביר חסנה", 30.46444444, 33.78361111), "mitla": pl("מעבר המיתלה", 30.04944444, 33.02416667),
    "gidi": pl("מעבר הגידי", 30.21666667, 33.16666667), "nakhl": pl("נח'ל", 29.91, 33.748), "dan": pl("קיבוץ דן", 33.23994812, 35.6535801, "נקודת הקיבוץ"),
    "teldan": pl("תל דן", 33.249, 35.652), "roshpina": pl("ראש פינה", 32.96908499, 35.54245743, "נקודת היישוב"), "afula": pl("עפולה", 32.61, 35.29, "נקודת העיר"),
    "jericho": pl("יריחו", 31.85611111, 35.46305556, "נקודת העיר"), "olives": pl("הר הזיתים", 31.78333333, 35.25083333)})
P = {k: [v["lat"], v["lon"]] for k, v in PLACES.items()}
D1A = D1["areas"]
AREAS = {"lahfan": D1A["lahfan"],
         "zahra": {"name": "תל א-זהרה וציר ירושלים–רמאללה", "bounds": [[31.835, 35.19], [31.885, 35.235]], "precision": "approximate",
                   "basis": "המקור כותב \"תל א-זהרה\" וציר ירושלים–רמאללה; אין קואורדינטות לתל, ולכן מלבן שציירנו על הציר"},
         "dothan": {"name": "עמק דותן", "bounds": [[32.36, 35.2], [32.44, 35.34]], "precision": "approximate", "basis": "המקור: עמק דותן וצומת קבטיה; מלבן שציירנו (אין קואורדינטה בערך)"}}
EVENTS = []
def ev(i, area, clock, a, b, unit, title, quote, geom=None, nopos=None, note="", prec="exact", at=0):
    EVENTS.append({"id": i, "t": clock, "time_label": clock, "start_min": a, "end_min": b, "time_precision": prec, "unit": unit, "title": title, "quote": quote,
                   "geometry": geom or [], "no_position": nopos or [], "note": note, "area": area, "_at": at})
mk = lambda place, kind, note="": {"type": "marker", "place": place, "kind": kind, "note": note}
tr = lambda a, b, label: {"type": "track", "from": a, "to": b, "label": label}
ar = lambda area, label: {"type": "area", "area": area, "label": label}
